import subprocess
import pymupdf as fitz

base='2a9f98fe95bd2ec5cc605000e2d52fd2960eea17'
head='ac824d6567d4e9b458254967bbfe11e45f7fdc9b'
A4W, A4H = 595.0, 842.0

def load(rev, path):
    data=subprocess.check_output(['git','show',f'{rev}:{path}'])
    return fitz.open(stream=data, filetype='pdf')

files = [f for f in subprocess.check_output(['git','diff','--name-only',base,head], text=True).splitlines() if f.endswith('.pdf')]

def overflow_pages(doc, slop=2.0):
    hits=[]
    for i, page in enumerate(doc):
        for inf in page.get_image_info():
            bb=fitz.Rect(inf['bbox'])
            if bb.x0 < -slop or bb.y0 < -slop or bb.x1 > page.rect.width+slop or bb.y1 > page.rect.height+slop:
                hits.append((i, tuple(round(x,1) for x in bb), (round(page.rect.width), round(page.rect.height)), page.get_text('text')[:80].replace('\n',' | ')))
                break
    return hits

print('=== overflow at HEAD ===')
for path in files:
    doc=load(head, path)
    hits=overflow_pages(doc)
    if hits:
        print(f'\n{path} pages={doc.page_count} overflow={len(hits)}')
        for h in hits[:8]:
            print(' ', h)
        if len(hits)>8:
            print(f'  ... +{len(hits)-8} more')
    doc.close()

print('\n=== overflow at BASE ===')
for path in files:
    if not path.startswith('output/lq/'): continue
    doc=load(base, path)
    hits=overflow_pages(doc)
    if hits:
        print(f'\n{path} pages={doc.page_count} overflow={len(hits)}')
        for h in hits[:6]:
            print(' ', h)
    doc.close()
